document.addEventListener('DOMContentLoaded', () => {
    const addCardBtn = document.getElementById('addCardBtn');
    const cardModal = document.getElementById('cardModal');
    const modalTitle = document.getElementById('modalTitle');
    const cardForm = document.getElementById('cardForm');
    const saveCardBtn = document.querySelector('.btn-primary');

    // --- Modal Handlers ---

    addCardBtn.addEventListener('click', () => {
        modalTitle.textContent = 'Crear Nueva Tarjeta';
        document.getElementById('cardId').value = ''; // Clear ID if present
        document.getElementById('title').value = '';
        document.getElementById('description').value = '';
        document.getElementById('priority').value = 'media';
        cardForm.reset();
        cardModal.style.display = 'block';
    });

    function closeModal() {
        cardModal.style.display = 'none';
    }

    window.addEventListener('click', (event) => {
        if (event.target === cardModal) {
            closeModal();
        }
    });

    // --- Card Submission Handler ---

    saveCardBtn.addEventListener('click', saveCard);

    function saveCard() {
        const title = document.getElementById('title').value.trim();
        const description = document.getElementById('description').value.trim();
        const priority = document.getElementById('priority').value;
        const cardId = document.getElementById('cardId').value.trim();

        if (!title) {
            alert('El título es obligatorio.');
            return;
        }

        if (cardId) {
            // Editar tarjeta existente
            updateCard(cardId, title, description, priority);
        } else {
            // Crear nueva tarjeta
            createAndAddCard(title, description, priority);
        }

        closeModal();
    }

    function createAndAddCard(title, description, priority) {
        const newCard = document.createElement('div');
        newCard.className = 'card card-container';
        newCard.setAttribute('data-id', Date.now().toString()); // Simple unique ID for demonstration

        // Determine the initial column (always Pending/Pendiente)
        const targetColumnContainer = document.getElementById('cards-pendiente');

        if (!targetColumnContainer) {
            console.error("Error: No se encontró el contenedor de tarjetas 'Pendiente'.");
            return;
        }

        // Build the card HTML structure
        newCard.innerHTML = `
            <div class="card-body">
                <h5 class="card-title">${title}</h5>
                ${description ? `<p class="card-description">${description}</p>` : ''}
                <span class="priority-tag priority-${priority}">Prioridad: ${getPriorityText(priority)}</span>
            </div>
            <div class="card-actions">
                <button class="action-btn" onclick="editCard('${newCard.getAttribute('data-id')}')">Editar</button>
                <button class="action-btn btn-secondary" onclick="deleteCard('${newCard.getAttribute('data-id')}')">Eliminar</button>
            </div>
        `;

        // FIX: Append the new card to the 'Pendiente' container
        targetColumnContainer.appendChild(newCard);
    }

    function updateCard(cardId, title, description, priority) {
        const cardElement = document.querySelector(`.card-container[data-id="${cardId}"]`);
        if (!cardElement) {
            alert('Tarjeta no encontrada para actualizar.');
            return;
        }

        // Update content
        cardElement.querySelector('.card-title').textContent = title;
        const descriptionElement = cardElement.querySelector('.card-description');
        if (description) {
            descriptionElement.textContent = description;
        } else {
            descriptionElement.remove(); // Remove if empty
        }

        // Update priority tag
        const oldPriorityTag = cardElement.querySelector('.priority-tag');
        oldPriorityTag.className = `priority-tag priority-${priority}`;
        oldPriorityTag.innerHTML = `Prioridad: ${getPriorityText(priority)}`;
    }


    // --- Utility Functions (Global scope for inline onclick handlers) ---

    window.editCard = function(cardId) {
        const cardElement = document.querySelector(`.card-container[data-id="${cardId}"]`);
        if (!cardElement) return;

        const title = cardElement.querySelector('.card-title').textContent;
        const description = cardElement.querySelector('.card-description') ? cardElement.querySelector('.card-description').textContent : '';
        const priorityTag = cardElement.querySelector('.priority-tag');
        const currentPriority = priorityTag ? priorityTag.className.split(' ').find(cls => cls.startsWith('priority-'))?.replace('priority-', '') : 'media';

        // Populate modal fields for editing
        document.getElementById('cardId').value = cardId;
        document.getElementById('title').value = title;
        document.getElementById('description').value = description;
        document.getElementById('priority').value = currentPriority;

        modalTitle.textContent = 'Editar Tarjeta';
        cardModal.style.display = 'block';
    }

    window.deleteCard = function(cardId) {
        if (confirm('¿Estás seguro de que quieres eliminar esta tarjeta?')) {
            const cardElement = document.querySelector(`.card-container[data-id="${cardId}"]`);
            if (cardElement) {
                cardElement.remove();
            }
        }
    }

    function getPriorityText(priority) {
        switch (priority) {
            case 'alta': return 'Alta';
            case 'media': return 'Media';
            case 'baja': return 'Baja';
            default: return 'Desconocida';
        }
    }

    // --- Drag and Drop Handlers ---

    const columns = document.querySelectorAll('.column');

    columns.forEach(column => {
        column.addEventListener('dragover', (e) => {
            e.preventDefault(); // Necessary to allow dropping
            const afterElement = getDragAfterElement(column, e.clientY);
            const draggable = document.querySelector('.dragging');
            if (draggable) {
                // Visual feedback for where the card will land
                if (afterElement == null) {
                    column.appendChild(draggable);
                } else {
                    column.insertBefore(draggable, afterElement);
                }
            }
        });

        column.addEventListener('drop', (e) => {
            e.preventDefault();
            const card = document.querySelector('.card-container');
            if (card && column.id !== 'col-pendiente') { // Only update status if dropped into a different column than the initial creation point
                // Update data attribute and potentially save state here
                console.log(`Tarjeta movida a ${column.dataset.status}`);
            }
        });
    });

    // --- Dragging Handlers for Cards ---

    document.addEventListener('dragstart', (e) => {
        if (e.target.closest('.card-container')) {
            const card = e.target.closest('.card-container');
            card.classList.add('dragging');
            e.dataTransfer.setData('text/plain', card.dataset.id); // Store ID if needed for complex logic
        }
    });

    document.addEventListener('dragend', (e) => {
        if (e.target.closest('.card-container')) {
            e.target.closest('.card-container').classList.remove('dragging');
        }
    });


    // --- Helper Functions for Drag and Drop ---

    function getDragAfterElement(container, y) {
        const cur = document.querySelector('.dragging');
        if (!cur) return null;

        const[] = [...container.querySelectorAll('.card-container:not(.dragging)')];

        return Array.from(container.querySelectorAll('.card-container:not(.dragging)'))
            .reduce((closest, child) => {
                const box = child.getBoundingClientRect();
                const offset = y - box.top - box.height / 2; // Calculate distance from center
                if (offset < 0 && offset > closest.offset) {
                    return { offset: offset, element: child };
                } else {
                    return closest;
                }
            }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

});
