        actionsDiv.className = 'card-actions';
        actionsDiv.innerHTML = '<button class="action-btn btn-secondary">Ver detalles</button>';


        // Assemble the card body
        cardBody.appendChild(titleElement);
        cardBody.appendChild(descriptionElement);
        cardBody.appendChild(priorityTag);
        cardBody.appendChild(actionsDiv);

        // Assemble the final card container
        cardContainer.appendChild(dragHandle);
        cardContainer.appendChild(cardBody);

        return cardContainer;
    };


    // --- Drag and Drop Logic (Simplified for this fix) ---
    const setupDragAndDrop = () => {
        const columns = document.querySelectorAll('.column');

        columns.forEach(column => {
            // Make the column droppable
            column.addEventListener('dragover', (e) => {
                e.preventDefault(); // Necessary to allow dropping
                column.classList.add('drag-over');
            });

            column.addEventListener('dragleave', () => {
                column.classList.remove('drag-over');
            });

            column.addEventListener('drop', (e) => {
                e.preventDefault();
                const draggedCard = document.querySelector('.dragging');
                if (draggedCard && column.id !== 'col-pendiente') { // Prevent dropping back to source if logic is complex
                    // Append the card to the correct container within the dropped column
                    const targetContainer = column.querySelector('.cards-' + column.id.split('-')[1]);
                    if (targetContainer) {
                        targetContainer.appendChild(draggedCard);
                    }
                }
                column.classList.remove('drag-over');
            });
        });

        // Make cards draggable
        document.querySelectorAll('.card-container').forEach(card => {
            card.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', e.target.id || 'card'); // Use a generic identifier
                e.target.classList.add('dragging');
            });

            card.addEventListener('dragend', (e) => {
                e.target.classList.remove('dragging');
            });
        });
    };

    setupDragAndDrop();
});
