// Global variables to manage state
let currentColumn = 'pendiente'; // Default column when starting or adding a card
const columns = ['pendiente', 'en-curso', 'completa'];

// --- DOM Elements Cache ---
const elements = {
    addCardBtn: document.getElementById('addCardBtn'),
    colPendiente: document.getElementById('col-pendiente'),
    cardsPendiente: document.getElementById('cards-pendiente'),
    addCardBtnBottom: document.getElementById('addCardBtnBottom'),
    colEnCurso: document.getElementById('col-en-curso'),
    cardsEnCurso: document.getElementById('cards-en-curso'),
    colCompleta: document.getElementById('col-completa'),
    cardsCompleta: document.getElementById('cards-completa'),
    cardModal: document.getElementById('cardModal'),
    modalTitle: document.getElementById('modalTitle'),
    cardForm: document.getElementById('cardForm'),
    cardIdInput: document.getElementById('cardId'),
    currentColumnDisplay: document.getElementById('currentColumn'),
    titleInput: document.getElementById('title'),
    descriptionInput: document.getElementById('description'),
    priorityInput: document.getElementById('priority'),
    saveCardBtn: document.getElementById('saveCardBtn')
};

// --- Initialization and Event Listeners ---

document.addEventListener('DOMContentLoaded', () => {
    setupEventListeners();
    // Initialize the board state (optional, but good practice)
});

function setupEventListeners() {
    elements.addCardBtn.addEventListener('click', openAddCardModal);
    elements.addCardBtnBottom.addEventListener('click', openAddCardModal);
    elements.cardForm.addEventListener('submit', handleSaveCardSubmit);
    elements.cardModal.addEventListener('click', (e) => {
        if (e.target === elements.cardModal) {
            closeAddCardModal();
        }
    });

    // Setup drag and drop listeners for columns
    setupDragAndDropListeners();
}

/**
 * Opens the modal for adding a new card.
 */
function openAddCardModal() {
    elements.modalTitle.textContent = 'Crear Nueva Tarjeta';
    elements.cardForm.reset();
    elements.cardModal.style.display = 'block';
    // Ensure the current column is set correctly when opening the modal
    updateCurrentColumnDisplay(currentColumn);
}

/**
 * Closes the card creation modal.
 */
function closeAddCardModal() {
    elements.cardModal.style.display = 'none';
}

/**
 * Handles the submission of the card form data.
 * @param {Event} e - The submit event.
 */
function handleSaveCardSubmit(e) {
    e.preventDefault();

    const title = elements.titleInput.value.trim();
    const description = elements.descriptionInput.value.trim();
    const priority = elements.priorityInput.value;

    if (!title) {
        alert('El título es obligatorio.');
        return;
    }

    // 1. Create the card data object
    const newCardData = {
        id: Date.now().toString(), // Simple unique ID
        title: title,
        description: description,
        priority: priority || 'media',
        status: currentColumn,
        createdAt: new Date().toISOString()
    };

    // 2. Render the card element
    const cardElement = renderCard(newCardData);

    // 3. Append the card to the correct column container (FIX APPLIED HERE)
    appendCardToColumn(cardElement, currentColumn);

    closeAddCardModal();
}


/**
 * Renders a single card element from card data.
 * @param {Object} cardData - The data for the card.
 * @returns {HTMLElement} The fully constructed card DOM element.
 */
function renderCard(cardData) {
    const card = document.createElement('div');
    card.className = 'card-container';
    card.setAttribute('data-id', cardData.id);
    card.setAttribute('draggable', true);

    // Card Body Content
    const body = document.createElement('div');
    body.className = 'card-body';

    // Title
    const titleEl = document.createElement('h4');
    titleEl.className = 'card-title';
    titleEl.textContent = cardData.title;

    // Description (optional)
    if (cardData.description) {
        const descriptionEl = document.createElement('p');
        descriptionEl.className = 'card-description';
        descriptionEl.textContent = cardData.description;
        body.appendChild(descriptionEl);
    }

    // Priority Tag
    const priorityTag = document.createElement('span');
    priorityTag.className = `priority-tag priority-${cardData.priority}`;
    priorityTag.textContent = cardData.priority.toUpperCase();
    body.prepend(priorityTag); // Put tag at the top of body

    // Actions (Placeholder for future actions)
    const actionsDiv = document.createElement('div');
    actionsDiv.className = 'card-actions';
    // Add action buttons if needed later

    body.appendChild(titleEl);
    body.appendChild(actionsDiv);


    // Assemble the card
    card.appendChild(body);

    return card;
}

/**
 * Appends a rendered card element to the specified column container.
 * @param {HTMLElement} cardElement - The card DOM element.
 * @param {string} status - The ID of the target column (e.g., 'pendiente').
 */
function appendCardToColumn(cardElement, status) {
    let targetContainer = null;

    switch (status) {
        case 'pendiente':
            targetContainer = elements.cardsPendiente;
            break;
        case 'en-curso':
            targetContainer = elements.cardsEnCurso;
            break;
        case 'completa':
            targetContainer = elements.cardsCompleta;
            break;
    }

    if (targetContainer) {
        // FIX: Ensure the card is appended to the correct container element
        targetContainer.appendChild(cardElement);
    } else {
        console.error(`Target container for status '${status}' not found.`);
    }
}


/**
 * Updates the display text showing which column is currently active/selected.
 * @param {string} status - The ID of the current column.
 */
function updateCurrentColumnDisplay(status) {
    const display = document.getElementById('currentColumn');
    if (display) {
        // Capitalize and replace hyphens for better readability in the UI
        let readableStatus = status.replace('-', ' ').toUpperCase();
        display.textContent = `Columna actual: ${readableStatus}`;
    }
}

/**
 * --- Drag and Drop Functionality ---
 */

function setupDragAndDropListeners() {
    // 1. Make card containers draggable (dragstart)
    document.querySelectorAll('.card-container').forEach(card => {
        card.addEventListener('dragstart', handleDragStart);
    });

    // 2. Setup drop zones on columns
    const columnContainers = [
        elements.colPendiente,
        elements.colEnCurso,
        elements.colCompleta
    ];

    columnContainers.forEach(column => {
        // Drag over listener (prevents default to allow dropping)
        column.addEventListener('dragover', handleDragOver);
        // Drop listener (handles the actual drop event)
        column.addEventListener('drop', handleDrop);
    });
}

/**
 * Handles the dragstart event on a card element.
 * @param {DragEvent} e - The drag event.
 */
function handleDragStart(e) {
    // Set data to be transferred (the ID of the card being dragged)
    e.dataTransfer.setData('text/plain', e.target.dataset.id);
    e.dataTransfer.effectAllowed = 'move';

    // Optional: Add a class to visually indicate dragging
    setTimeout(() => {
        e.target.classList.add('dragging');
    }, 0);
}

/**
 * Handles the dragover event on a column container.
 * @param {DragEvent} e - The drag event.
 */
function handleDragOver(e) {
    e.preventDefault(); // Necessary to allow dropping
    e.dataTransfer.dropEffect = 'move';
}

/**
 * Handles the drop event when a card is dropped into a column container.
 * @param {DragEvent} e - The drop event.
 */
function handleDrop(e) {
    e.preventDefault();

    const draggedCardId = e.dataTransfer.getData('text/plain');
    const draggedElement = document.querySelector(`.card-container[data-id="${draggedCardId}"]`);
    if (!draggedElement) return;

    // Determine the target column container (the parent of the drop event)
    let targetColumnContainer = e.currentTarget;
    let newStatus = '';

    // Identify the status based on which column element was dropped onto
    if (targetColumnContainer === elements.colPendiente) {
        newStatus = 'pendiente';
    } else if (targetColumnContainer === elements.colEnCurso) {
        newStatus = 'en-curso';
    } else if (targetColumnContainer === elements.colCompleta) {
        newStatus = 'completa';
    }

    if (newStatus && draggedElement) {
        // 1. Update the DOM structure: Move the element
        targetColumnContainer.querySelector('.cards-pendiente, .cards-en-curso, .cards-completa')
            ? targetColumnContainer.querySelector(`[data-column="${newStatus}"]`) // Assuming a data attribute or direct ID usage for container selection if needed
            : null;

        // Since the containers are siblings of the column header, we append directly to the parent container element (the one with class 'board')
        // Wait, based on IDs: cards-pendiente is the target. We must find which specific container holds the cards.
        let cardContainerId = `cards-${newStatus}`;
        const actualCardContainer = document.getElementById(cardContainerId);

        if (actualCardContainer) {
            // Remove dragging class first
            draggedElement.classList.remove('dragging');

            // Append the element to the correct container
            actualCardContainer.appendChild(draggedElement);
        }


        // 2. Update the card's internal data state (if we were using a global state management system)
        // For this simple implementation, we just update the UI and current column display.

        // 3. Update the application state/UI indicator
        currentColumn = newStatus;
        updateCurrentColumnDisplay(newStatus);
    }
}


/**
 * --- Utility Functions (Not directly related to the fix but kept for completeness) ---
 */

function getPriorityClass(priority) {
    switch (priority.toLowerCase()) {
        case 'alta': return 'priority-alta';
        case 'media': return 'priority-media';
        case 'baja': return 'priority-baja';
        default: return 'priority-media';
    }
}

// Note: The original script structure was maintained, focusing the fix on `appendCardToColumn` 
