```javascript
function createCardElement(title, description, priority) {
    const cardsContainer = document.getElementById('cards-pendiente');
    if (!cardsContainer) return;

    // 1. Create the main card element
    const card = document.createElement('div');
    card.className = 'card';
    card.setAttribute('draggable', true);
    card.dataset.title = title; // Store data for drag/drop identification

    // 2. Build the inner HTML structure
    let descriptionHtml = '';
    if (description) {
        descriptionHtml = `<p class="card-description">${description}</p>`;
    }

    const cardHTML = `
        <div class="card-body">
            <h4 class="card-title">${title}</h4>
            ${descriptionHtml}
            <div class="priority-tag ${getPriorityClass(priority)}">${priority.toUpperCase()}</div>
        </div>
        <div class="card-actions">
            <!-- Actions buttons can go here if needed -->
        </div>
    `;

    card.innerHTML = cardHTML;

    // 3. Append to the container (This ensures it lands in 'Pendiente')
    cardsContainer.appendChild(card);

    // 4. Re-attach drag listeners to the new card
    setupCardDragListeners(card);
}
