function handleDrop(e) {
    e.preventDefault();
    const dropZone = e.target.closest('.column');

    // Clean up visual feedback
    document.querySelectorAll('.column').forEach(col => col.style.borderRight = 'none');

    if (dropZone) {
        const cardTitle = e.dataTransfer.getData('text/plain');
        const targetColumnId = dropZone.id;

        // Find the actual card element that was dragged (we use data-title for identification)
        const cardsContainer = document.getElementById(`cards-${targetColumnId}`);
        if (!cardsContainer) return;

        // 1. Get the original card element from the DOM based on its title/data attribute
        let cardToMove = null;
        document.querySelectorAll('.card').forEach(card => {
            if (card.dataset.title === cardTitle) {
                cardToMove = card;
            }
        });

        if (cardToMove) {
            // 2. Append the found element to the new container
            cardsContainer.appendChild(cardToMove);
        }
    }
}
