// Global state variables (assuming these exist)
let cards = [];
let currentColumnId = null;

/**
 * Initializes event listeners and sets up the board structure.
 */
function initializeBoard() {
    // 1. Setup drag and drop listeners on columns
    const columns = document.querySelectorAll('.column');
    columns.forEach(col => {
        col.addEventListener('dragover', handleDragOver);
        col.addEventListener('drop', handleDrop);
    });

    // 2. Setup card creation button listener (assuming addCardBtn is the main trigger)
    const addCardButton = document.getElementById('addCardBtn');
    if (addCardButton) {
        addCardButton.addEventListener('click', () => openModal(null));
    }

    // 3. Setup card form submission listener
    document.getElementById('cardForm').addEventListener('submit', saveCard);

    // Initial board setup: Ensure all columns and buttons are correctly placed/visible
    setupBoardStructure();
}

/**
 * Sets up the structure, ensuring only 'Pendiente' gets the add button.
 */
function setupBoardStructure() {
    const columnContainers = document.querySelectorAll('.column');
    const addCardButtonTemplate = document.createElement('button');
    addCardButtonTemplate.id = 'addCardBtn'; // Use a template ID if needed, but we'll clone/re-use the logic

    // Clear any existing buttons first to prevent duplication on re-runs
    document.querySelectorAll('.column-actions').forEach(actions => {
        const existingButtons = actions.querySelectorAll('.add-card-button');
        existingButtons.forEach(btn => btn.remove());
    });


    columnContainers.forEach(col => {
        // Assuming the button element is created/managed here or needs to be appended conditionally

        // Check if this column is 'Pendiente' (assuming a way to identify it, e.g., class name or ID)
        if (col.id === 'col-pendiente') {
            const actionsContainer = col.querySelector('.column-actions');
            if (actionsContainer) {
                // Create the button only for Pendiente
                let addCardBtn = document.createElement('button');
                addCardBtn.className = 'action-btn btn-primary add-card-button';
                addCardBtn.textContent = 'Agregar tarjeta';
                addCardBtn.setAttribute('data-column-id', col.id);
                addCardBtn.addEventListener('click', () => openModal(null));

                // Append the button to the actions container
                actionsContainer.appendChild(addCardBtn);
            }
        } else {
             // Ensure no button is added to other columns
             const actionsContainer = col.querySelector('.column-actions');
             if (actionsContainer) {
                 // Clear any potential buttons from non-pendiente columns if they exist
                 const existingButtons = actionsContainer.querySelectorAll('.add-card-button');
                 existingButtons.forEach(btn => btn.remove());
             }
        }
    });

    // Initial rendering of cards (if necessary)
    renderCards();
}


/**
 * Handles dragover event for a column.
 */
function handleDragOver(e) {
    e.preventDefault();
    const targetColumn = e.currentTarget;
    targetColumn.classList.add('drag-over');
}

/**
 * Handles dragleave event (optional, but good practice).
 */
// Note: If the original code had a handleDragLeave function, it should be kept/restored here.

/**
 * Handles drop event for a column.
 */
function handleDrop(e) {
    e.preventDefault();
    const targetColumn = e.currentTarget;
    targetColumn.classList.remove('drag-over');

    if (e.dataTransfer.getData("cardId")) {
        const cardId = e.dataTransfer.getData("cardId");
        const cardElement = document.getElementById(cardId);
        if (cardElement) {
            // Update the card's column and position in the data model
            const newColumnId = targetColumn.id;
            moveCardToColumn(cardId, newColumnId);

            // Visually move the card
            targetColumn.querySelector('.cards-container') ? 
                targetColumn.querySelector('.cards-container').appendChild(cardElement) :
                targetColumn.appendChild(cardElement);
        }
    }
}


/**
 * Opens the modal for creating or editing a card.
 * @param {string|null} cardId - ID of the card to edit, or null if creating new.
 */
function openModal(cardId) {
    const modal = document.getElementById('cardModal');
    const form = document.getElementById('cardForm');

    if (cardId) {
        // Editing existing card
        const cardData = cards.find(c => c.id === cardId);
        if (!cardData) return;

        document.getElementById('modalTitle').textContent = 'Editar tarjeta';
        form.dataset.editingCardId = cardId;
        document.getElementById('cardId').value = cardId;
        document.getElementById('title').value = cardData.title;
        document.getElementById('description').value = cardData.description;
        document.getElementById('priority').value = cardData.priority;

    } else {
        // Creating new card
        document.getElementById('modalTitle').textContent = 'Crear nueva tarjeta';
        form.dataset.editingCardId = '';
        document.getElementById('cardId').value = '';
        document.getElementById('title').value = '';
        document.getElementById('description').value = '';
        document.getElementById('priority').value = 'media'; // Default priority
    }

    modal.style.display = 'block';
}


/**
 * Saves the card data, either creating a new card or updating an existing one.
 */
function saveCard(e) {
    e.preventDefault();
    const form = e.target;
    const isEditing = form.dataset.editingCardId;

    const title = document.getElementById('title').value.trim();
    const description = document.getElementById('description').value.trim();
    const priority = document.getElementById('priority').value;

    if (!title) {
        alert("El título es obligatorio.");
        return;
    }

    let cardId;
    let cardData;

    if (isEditing) {
        cardId = isEditing;
        // Update existing card data
        const index = cards.findIndex(c => c.id === cardId);
        if (index !== -1) {
            cardData = { ...cards[index], title, description, priority };
            cards[index] = cardData;
        } else {
             // Should not happen if logic is correct
             console.error("Card to edit not found.");
             return;
        }
    } else {
        // Create new card
        cardId = 'card-' + Date.now();
        cardData = { id: cardId, title, description, priority, columnId: currentColumnId };
        cards.push(cardData);
    }

    closeModal();
    renderCards();
}


/**
 * Closes the modal window.
 */
function closeModal() {
    document.getElementById('cardModal').style.display = 'none';
}


/**
 * Renders all cards from the global state array into the DOM.
 */
function renderCards() {
    // Clear existing cards first
    document.querySelectorAll('.cards-container').forEach(container => container.innerHTML = '');

    cards.forEach(cardData => {
        const cardElement = createCardElement(cardData);
        const targetContainer = document.querySelector(`#${cardData.columnId} .cards-container`);
        if (targetContainer) {
            targetContainer.appendChild(cardElement);
        } else {
             console.warn(`Could not find container for column ${cardData.columnId}`);
        }
    });
}

/**
 * Creates the DOM element for a single card.
 * @param {object} cardData - The data object of the card.
 * @returns {HTMLElement} The fully constructed card element.
 */
function createCardElement(cardData) {
    const card = document.createElement('div');
    card.className = 'card';
    card.id = cardData.id;
    card.setAttribute('draggable', true);
    card.dataset.cardId = cardData.id;

    // Title and Description
    const titleElement = document.createElement('h4');
    titleElement.className = 'card-title';
    titleElement.textContent = cardData.title;

    const descriptionElement = document.createElement('p');
    descriptionElement.className = 'card-description';
    descriptionElement.textContent = cardData.description || 'Sin descripción.';

    // Priority Tag
    const priorityTag = document.createElement('span');
    priorityTag.className = `priority-tag priority-${cardData.priority}`;
    priorityTag.textContent = cardData.priority.toUpperCase();

    // Actions (Edit/Delete)
    const actionsContainer = document.createElement('div');
    actionsContainer.className = 'card-actions';

    const editBtn = document.createElement('button');
    editBtn.className = 'action-btn btn-secondary';
    editBtn.textContent = 'Editar';
    editBtn.addEventListener('click', () => openModal(cardData.id));

    // Add drag handle functionality (optional, but good practice)
    const dragHandle = document.createElement('div');
    dragHandle.className = 'drag-handle';
    dragHandle.style.cursor = 'grab';


    card.appendChild(titleElement);
    card.appendChild(descriptionElement);
    card.appendChild(priorityTag);
    card.appendChild(actionsContainer);
    card.appendChild(editBtn); // Placing edit button here for simplicity

    // Drag listeners setup
    card.addEventListener('dragstart', handleDragStart);

    return card;
}


/**
 * Handles dragstart event when dragging a card.
 */
function handleDragStart(e) {
    const cardId = e.target.dataset.cardId;
    if (cardId) {
        e.dataTransfer.setData("cardId", cardId);
        // Optional: Add visual feedback while dragging
        setTimeout(() => {
            e.target.classList.add('dragging');
        }, 0);
    }
}

/**
 * Updates the data model when a card is moved between columns.
 * @param {string} cardId - The ID of the card being moved.
 * @param {string} newColumnId - The ID of the target column.
 */
function moveCardToColumn(cardId, newColumnId) {
    const cardIndex = cards.findIndex(c => c.id === cardId);
    if (cardIndex !== -1 && cards[cardIndex].columnId !== newColumnId) {
        cards[cardIndex].columnId = newColumnId;
        // Optionally, update the currentColumnId if needed globally
        currentColumnId = newColumnId; 
    }
}

// Initialize the application when the DOM is fully loaded
document.addEventListener('DOMContentLoaded', initializeBoard);
