            e.preventDefault();
            const afterElement = getDragAfterElement(column, e.clientY);
            if (afterElement == null) {
                column.querySelector('.cards-container').appendChild(e.dataTransfer.getData('text/plain'));
            } else {
                afterElement.parentNode.insertBefore(e.dataTransfer.getData('text/plain'), afterElement);
            }
        });
    });

    // Initial setup (if needed)
    initializeBoard();


    /**
     * Handles the submission of the card form.
