    function handleSaveCard(e) {
        e.preventDefault();

        const title = document.getElementById('title').value.trim();
        const description = document.getElementById('description').value.trim();
        const priority = document.getElementById('priority').value;

        if (!title) {
            alert('Por favor, ingresa un título para la tarjeta.');
            return;
        }

        // 1. Create the card element structure
        const newCardElement = createCardElement(title, description, priority);

        // 2. Determine the target column (always 'Pendiente' when creating)
        const targetColumnContainer = document.getElementById('cards-pendiente');

        if (targetColumnContainer) {
            // 3. Append the card to the correct container
            targetColumnContainer.appendChild(newCardElement);
        } else {
            console.error("Error: No se encontró el contenedor de tarjetas 'Pendiente'.");
        }


        // 4. Reset form and close modal
        cardForm.reset();
        modal.classList.add('hidden');
        document.body.style.overflow = '';

        alert(`Tarjeta "${title}" creada con éxito en Pendiente.`);
    }

    /**
     * Creates the full DOM element for a new card.
     * @param {string} title - The title of the card.
     * @param {string} description - The description of the card.
     * @param {('alta'|'media'|'baja')} priority - The priority level.
     * @returns {HTMLElement} The fully constructed card element.
     */
    function createCardElement(title, description, priority) {
        const card = document.createElement('div');
        card.className = 'card-container';
        card.setAttribute('draggable', true);
        card.dataset.title = title; // Useful for drag/drop identification

        // Drag handle (optional but good practice)
        const dragHandle = document.createElement('div');
        dragHandle.className = 'drag-handle';
        dragHandle.innerHTML = '&#x2630;'; // Handle icon

        // Card body content
        const cardBody = document.createElement('div');
        cardBody.className = 'card-body';

        // Title
        const titleElement = document.createElement('h4');
        titleElement.className = 'card-title';
        titleElement.textContent = title;

        // Description
        const descriptionElement = document.createElement('p');
        descriptionElement.className = 'card-description';
        descriptionElement.textContent = description || 'Sin descripción.';

        // Priority Tag
        const priorityTag = document.createElement('span');
        priorityTag.className = `priority-tag priority-${priority}`;
        priorityTag.textContent = `Prioridad: ${priority.charAt(0).toUpperCase() + priority.slice(1)}`;


        // Actions (Placeholder for future actions)
        const actionsDiv = document.createElement('div');
        actionsDiv.className = 'card-actions';

        // Assemble the card
        card.appendChild(dragHandle);
        card.appendChild(cardBody);
        cardBody.appendChild(titleElement);
        cardBody.appendChild(descriptionElement);
        cardBody.appendChild(priorityTag);
        card.appendChild(actionsDiv);


        // Add drag event listeners to the card itself (for dragging)
        card.addEventListener('dragstart', (e) => {
            e.dataTransfer.setData('text/plain', title); // Use title as identifier for simplicity
            e.currentTarget.classList.add('dragging');
        });

        card.addEventListener('dragend', (e) => {
            e.currentTarget.classList.remove('dragging');
        });


        return card;
    }

    /**
     * Helper function to determine where an element should be dropped.
     * @param {HTMLElement} container - The parent column container.
     * @param {number} y - The vertical position of the mouse pointer.
     * @returns {HTMLElement | null} The element after which the dragged item should be placed, or null if it should go at the end.
     */
    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.card-container:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2; // Calculate distance from center of element
            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

