    const addCardBtn = document.getElementById('addCardBtn');
    const cardModal = document.getElementById('cardModal');
    const modalTitle = document.getElementById('modalTitle');
    const cardForm = document.getElementById('cardForm');
    const saveCardBtn = document.getElementById('saveCardBtn');

    // Event listener for opening the modal (assuming this is how creation starts)
    addCardBtn.addEventListener('click', () => {
        modalTitle.textContent = 'Crear Nueva Tarjeta';
        document.querySelector('#cardForm .form-group:nth-child(3)').style.display = 'none'; // Hide Description if needed for simple card creation
        saveCardBtn.textContent = 'Guardar Tarjeta';
        cardModal.classList.remove('hidden');
    });

    // Event listener for closing the modal
    document.querySelector('.close-modal').addEventListener('click', () => {
        cardModal.classList.add('hidden');
    });

    // Event listener for saving the card data
    saveCardBtn.addEventListener('click', (e) => {
        e.preventDefault();

        const title = document.getElementById('title').value.trim();
        const description = document.getElementById('description').value.trim();
        const priority = document.getElementById('priority').value;

        if (!title) {
            alert('El título es obligatorio.');
            return;
        }

        // 1. Create the card element
        const newCard = createCardElement(title, description, priority);

        // 2. Append the card to the 'Pendiente' column container
        const pendienteContainer = document.getElementById('cards-pendiente');
        if (pendienteContainer) {
            pendienteContainer.appendChild(newCard);
        } else {
            console.error("No se encontró el contenedor de tarjetas pendientes.");
        }

        // 3. Close modal and reset form
        cardModal.classList.add('hidden');
        cardForm.reset();
    });


    /**
     * Crea la estructura HTML para una nueva tarjeta.
     * @param {string} title - Título de la tarjeta.
     * @param {string} description - Descripción de la tarjeta.
     * @param {('alta'|'media'|'baja')} priority - Prioridad de la tarjeta.
     * @returns {HTMLElement} El elemento DOM de la nueva tarjeta.
     */
    function createCardElement(title, description, priority) {
        const card = document.createElement('div');
        card.className = 'card-container';

        // Card Title and Body
        const body = document.createElement('div');
        body.className = 'card-body';

        const titleEl = document.createElement('h4');
        titleEl.className = 'card-title';
        titleEl.textContent = title;

        const descriptionEl = document.createElement('p');
        descriptionEl.className = 'card-description';
        if (description) {
            descriptionEl.textContent = description;
        } else {
            descriptionEl.textContent = ''; // Keep it empty if no description
        }

        // Priority Tag
        const priorityTag = document.createElement('span');
        priorityTag.className = `priority-tag priority-${priority}`;
        priorityTag.textContent = `Prioridad: ${priority.charAt(0).toUpperCase() + priority.slice(1)}`;


        body.appendChild(titleEl);
        if (description) {
            body.appendChild(descriptionEl);
        }
        body.appendChild(priorityTag);

        card.appendChild(body);

        // Actions (Placeholder for future functionality, keeping structure intact)
        const actions = document.createElement('div');
        actions.className = 'card-actions';
        // Add action buttons here if needed later

        card.appendChild(actions);

        return card;
    }


    // --- Drag and Drop Functionality (Assuming this part was already working) ---

    const columns = document.querySelectorAll('.column');
    let draggedCard = null;

    columns.forEach(column => {
        // Setup drag start listener on cards within the column
        column.addEventListener('dragstart', (e) => {
            if (e.target.closest('.card-container')) {
                draggedCard = e.target.closest('.card-container');
                setTimeout(() => {
                    draggedCard.classList.add('dragging');
                }, 0);
                e.dataTransfer.setData('text/plain', 'card'); // Set data type for compatibility
            }
        });

        // Setup drag end listener on the column itself (or document)
        column.addEventListener('dragend', () => {
            if (draggedCard) {
                draggedCard.classList.remove('dragging');
                draggedCard = null;
            }
        });

        // Setup drop zone listeners on columns
        column.addEventListener('dragover', (e) => {
            e.preventDefault(); // Necessary to allow dropping
            const afterElement = getDragAfterElement(column, e.clientY);
            const currentDragging = document.querySelector('.dragging');
            if (currentDragging) {
                // Visual feedback for where the card will land
                if (afterElement == null) {
                    column.lastElementChild.parentNode.appendChild(currentDragging);
                } else {
                    afterElement.parentNode.insertBefore(currentDragging, afterElement);
                }
            }
        });

        column.addEventListener('drop', (e) => {
            e.preventDefault();
            if (draggedCard) {
                // Append the card to the drop zone container
                const targetColumn = e.currentTarget;
                targetColumn.querySelector('.cards-pendiente, .cards-en-curso, .cards-completa').appendChild(draggedCard);

                // Update status/data if necessary (omitted for minimal fix)
            }
        });
    });


    /**
     * Determina qué elemento debe ir después del cursor dentro de un contenedor.
     * @param {HTMLElement} container - El contenedor donde se está soltando la tarjeta.
     * @param {number} y - La posición Y del evento de ratón.
     * @returns {HTMLElement | null} El elemento que debería seguir al cursor, o null si debe ir al final.
     */
    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.card-container:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - (box.height / 2); // Calculate distance from center of element
            if (offset < closest.offset && offset > 0) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

});
