    // 1. Setup Drag and Drop Listeners on Columns
    const columns = [
        { id: 'pendiente', element: document.getElementById('cards-pendiente') },
        { id: 'en-curso', element: document.getElementById('cards-en-curso') },
        { id: 'completa', element: document.getElementById('cards-completa') }
    ];

    columns.forEach(col => {
        const columnElement = col.element;
        if (columnElement) {
            // Prevent default behavior for drag events on the drop zone
            columnElement.addEventListener('dragover', (e) => {
                e.preventDefault(); 
                columnElement.classList.add('drag-over');
            });

            columnElement.addEventListener('dragleave', () => {
                columnElement.classList.remove('drag-over');
            });

            // Handle the drop event
            columnElement.addEventListener('drop', (e) => {
                e.preventDefault();
                columnElement.classList.remove('drag-over');
                const draggedCard = document.querySelector('.dragging');
                if (draggedCard && draggedCard.dataset.cardId) {
                    handleDrop(draggedCard, col.id);
                }
            });
        }
