function setupDragListeners() {
    // Select all existing card elements
    const cards = document.querySelectorAll('.card-container');
    cards.forEach(card => {
        addCardDragEvents(card);
    });
}

function addCardDragEvents(card) {
    card.setAttribute('draggable', 'true');
    card.addEventListener('dragstart', (e) => {
        // Store the card ID and element reference for drop handling
        const cardId = card.dataset.cardId;
        e.dataTransfer.setData('text/plain', cardId);
        e.dataTransfer.effectAllowed = 'move';

        // Add a class to visually indicate dragging
        setTimeout(() => {
            card.classList.add('dragging');
        }, 0);
    });

    card.addEventListener('dragend', () => {
        // Remove the visual indicator when drag ends
        card.classList.remove('dragging');
    });
}


function handleDrop(draggedCard, targetColumnId) {
    const cardId = draggedCard.dataset.cardId;
    const oldColumnId = draggedCard.parentElement.id.replace('cards-', '');

    if (oldColumnId === targetColumnId) return; // No change

    // 1. Update DOM position
    const targetContainer = document.getElementById(`cards-${targetColumnId}`);
    if (targetContainer) {
        // Find the best place to drop (e.g., at the end, or before a specific element if implementing precise placement)
        // For simplicity and robustness, we append it for now, assuming visual order doesn't matter much on drop.
        targetContainer.appendChild(draggedCard);
    }

    // 2. Update State/Counters (The core fix)
    updateCardColumnState(cardId, oldColumnId, targetColumnId);
}


function updateCardColumnState(cardId, oldCol, newCol) {
    const card = document.querySelector(`.card-container[data-card-id="${cardId}"]`);
    if (!card) return;

    // 1. Update the internal state/database (simulated by updating the element's data attribute or calling a backend function)
    // Since we don't have a real backend, we assume this updates the card's status representation.
    card.dataset.column = newCol;

    // 2. Update Counters
    const counters = {
        pendiente: document.getElementById('count-pendiente'),
        en_curso: document.getElementById('count-en-curso'),
        completa: document.getElementById('count-completa')
    };

    // Decrement old column count
    if (counters[oldCol]) {
        let currentCount = parseInt(counters[oldCol].textContent) || 0;
        counters[oldCol].textContent = Math.max(0, currentCount - 1);
    }

    // Increment new column count
    if (counters[newCol]) {
        let currentCount = parseInt(counters[newCol].textContent) || 0;
        counters[newCol].textContent = currentCount + 1;
    }
}


