        createCard(title, description, priority, column);
    }

    closeModal();
}

function createCard(title, description, priority, initialColumn) {
    const card = document.createElement('div');
    card.className = 'card-container';
    card.dataset.cardId = Date.now().toString(); // Unique ID simulation
    card.dataset.column = initialColumn;

    card.innerHTML = `
        <div class="card-body">
            <h4 class="card-title">${title}</h4>
            <p class="card-description">${description}</p>
            <span class="priority-tag priority-${priority}">Prioridad: ${getPriorityText(priority)}</span>
        </div>
        <div class="card-actions">
            <!-- Placeholder for actions if needed -->
        </div>
    `;

    // Append to the correct column container
    const targetContainer = document.getElementById(`cards-${initialColumn}`);
    if (targetContainer) {
        targetContainer.appendChild(card);
    }

    // Update counters
    updateCounter('pendiente'); // Assuming new cards start in pendiente
    updateCardCount(initialColumn, 1);
}

function updateCard(cardId, title, description, priority, newColumn) {
    const card = document.querySelector(`.card-container[data-card-id="${cardId}"]`);
    if (!card) return;

    // Get old column state before updating
    const oldColumn = card.dataset.column || 'pendiente'; 

    // Update content
    card.querySelector('.card-title').textContent = title;
    card.querySelector('.card-description').textContent = description;
    card.querySelector('.priority-tag').className = `priority-tag priority-${priority}`;
    card.querySelector('.priority-tag').innerHTML = `Prioridad: ${getPriorityText(priority)}`;

    // Update internal state and move card if column changed
    if (oldColumn !== newColumn) {
        handleDrop(card, newColumn); // Use the existing drop handler logic
    } else {
        // If only content changes but stays in the same column
        card.dataset.column = newColumn;
    }
}

function getPriorityText(priority) {
    switch (priority) {
        case 'alta': return 'Alta';
        case 'media': return 'Media';
        case 'baja': return 'Baja';
        default: return 'Desconocida';
    }
}


// --- Counter and Initialization Logic ---

function updateCounter(columnId) {
