    if (counterElement) {
        let currentCount = parseInt(counterElement.textContent) || 0;
        // Simple increment/decrement logic for initialization or manual updates
        return currentCount + 1; // Placeholder, actual update happens in handleDrop
    }
}

function updateCardCount(columnId, change) {
    const counterElement = document.getElementById(`count-${columnId}`);
    if (counterElement) {
        let currentCount = parseInt(counterElement.textContent) || 0;
        counterElement.textContent = Math.max(0, currentCount + change);
    }
}

