function handleDrop(e) {
    e.preventDefault();
    const targetContainer = e.currentTarget;
    targetContainer.classList.remove('drag-over');

    // Retrieve data from dragstart event
    try {
        const data = JSON.parse(e.dataTransfer.getData('text/plain'));
        const draggedCardId = data.cardId;
        const sourceColumnId = data.sourceColumnId;
        const targetColumnId = e.currentTarget.id;

        if (!draggedCardId || !sourceColumnId) return;

        // 1. Get the card element to move
        let cardElement = document.querySelector(`.card[data-card-id="${draggedCardId}"]`);
        if (!cardElement) {
            console.error("Card not found:", draggedCardId);
            return;
        }

        // 2. Update DOM: Move the card element
        const oldContainer = document.getElementById(sourceColumnId).querySelector('.cards-container');
        const newContainer = targetContainer.querySelector('.cards-container');

        if (oldContainer && newContainer) {
            // Remove from old container and append to new one
            cardElement.remove(); 
            newContainer.appendChild(cardElement);
        } else {
             console.error("Containers not found.");
             return;
        }


        // 3. Update State/Counters (The core fix)
        updateCardPositionInState(draggedCardId, targetColumnId);

        // Adjust counters based on the move
        const sourceCounter = document.getElementById(`count-${sourceColumnId.split('-')[1]}`);
        const targetCounter = document.getElementById(`count-${targetColumnId.split('-')[1]}`);

        if (sourceCounter) {
            let currentCount = parseInt(sourceCounter.textContent);
            sourceCounter.textContent = Math.max(0, currentCount - 1);
        }

        if (targetCounter) {
            let currentCount = parseInt(targetCounter.textContent);
            targetCounter.textContent = currentCount + 1;
        }


    } catch (error) {
        console.error("Error handling drop:", error);
    }
}
