    const draggedCardElement = document.querySelector(`.card[data-card-id="${draggedCardId}"]`);
    if (!draggedCardElement) {
        console.error("Dragged card element not found.");
        return;
    }

    // 1. Determine the target column ID and name
    const targetColumn = document.querySelector(`.column[id="${targetContainer.closest('.column').id}"]`);
    if (!targetColumn) return;

    const sourceCounterElement = document.getElementById(`count-${sourceColumnId}`);
    const targetCounterElement = document.getElementById(`count-${targetColumn.id}`);

    // 2. Update DOM: Move the card element
    // Append the actual card element to the new container (cards-*)
    const targetCardContainer = targetColumn.querySelector('.card-container');
    if (targetCardContainer) {
        targetCardContainer.appendChild(draggedCardElement);
    }

    // 3. Update State/Counters
    updateCounter(sourceColumnId, -1); // Decrease source count
    updateCounter(targetColumn.id, 1);  // Increase target count

    // Optional: Re-run any necessary update logic if the card's position affects other elements (e.g., sorting)
}
