### FUNCION: renderCard
```js
function renderCard(card) {
    const cardContainer = document.createElement('div');
    cardContainer.className = 'card-container';
    cardContainer.id = `card-${card.id}`;
    cardContainer.innerHTML = `
        <div class="card">
            <div class="drag-handle" title="Arrastrar para cambiar de estado"></div>
            <div class="card-body">
                <h4 class="card-title">${card.title}</h4>
                <p class="card-description">${card.description}</p>
                <span class="priority-tag priority-${card.priority}">Prioridad: ${card.priority.toUpperCase()}</span>
            </div>
            <div class="card-actions">
                <!-- Aquí se pueden añadir acciones si es necesario -->
            </div>
        </div>
    `;

    const targetColumn = document.getElementById('cards-' + card.status.toLowerCase().replace(/\s/g, '-'));
    if (targetColumn) {
        targetColumn.appendChild(cardContainer.querySelector('.card'));
    }
}
