### BLOQUE: document.addEventListener('DOMContentLoaded', function() {
```js
document.addEventListener('DOMContentLoaded', function() {
    // 1. Inicializar el estado de las tarjetas y los eventos
    let cards = JSON.parse(localStorage.getItem('cards')) || [];
    if (cards.length === 0) {
        // Añadir algunas tarjetas de ejemplo si no hay ninguna guardada
        const exampleCards = [
            { id: 1, title: "Diseñar interfaz", description: "Crear maquetas iniciales para la web.", priority: "alta", status: "Pendiente", actions: [] },
            { id: 2, title: "Revisar código backend", description: "Asegurar que las APIs funcionen correctamente.", priority: "media", status: "En Curso", actions: [] },
            { id: 3, title: "Pruebas de usuario", description: "Recoger feedback y ajustar detalles finales.", priority: "baja", status: "Completa", actions: [] }
        ];
        cards = exampleCards;
        localStorage.setItem('cards', JSON.stringify(exampleCards));
    }

    // Limpiar el board antes de renderizar para evitar duplicados si se recarga la página
    document.getElementById('cards-pendiente').innerHTML = '';
    document.getElementById('cards-en-curso').innerHTML = '';
    document.getElementById('cards-completa').innerHTML = '';


    // Renderizar todas las tarjetas guardadas
    cards.forEach(card => {
        renderCard(card);
    });

    // 2. Configurar Event Listeners para el Modal de Creación de Tarjetas
    const addCardBtn = document.getElementById('addCardBtn');
    if (addCardBtn) {
        addCardBtn.addEventListener('click', openModal);
    }

    const addCardBtnBottom = document.getElementById('addCardBtnBottom');
    // Solo añadir listener si el botón existe y no es redundante con el principal
    if (addCardBtnBottom && !document.querySelector('.col-pendiente .card')) {
        addCardBtnBottom.addEventListener('click', openModal);
    }


    const modalCloseButton = document.getElementById('closeModal'); // Asumiendo que existe un botón de cierre en el modal
    if (modalCloseButton) {
        modalCloseButton.addEventListener('click', closeModal);
    }

    // Cerrar modal al hacer clic fuera del contenido
    document.getElementById('cardModal').addEventListener('click', function(e) {
        if (e.target === this) {
            closeModal();
        }
    });


    // 3. Configurar Event Listener para el Formulario de Creación de Tarjetas
    const cardForm = document.getElementById('cardForm');
    if (cardForm) {
        cardForm.addEventListener('submit', saveCard);
    }

    // 4. Implementar Drag and Drop (Mover tarjetas entre columnas)
    let draggedCard = null;

    document.querySelectorAll('.drag-handle').forEach(handle => {
        handle.setAttribute('draggable', true);
        handle.addEventListener('dragstart', function(e) {
            draggedCard = this.closest('.card');
            e.dataTransfer.setData('text/plain', draggedCard.id);
            setTimeout(() => {
                // Ocultar la tarjeta mientras se arrastra
                draggedCard.style.opacity = '0.5';
            }, 0);
        });

        handle.addEventListener('dragend', function() {
            // Restaurar opacidad al finalizar el arrastre
            if (draggedCard) {
                draggedCard.style.opacity = '1';
                draggedCard = null;
            }
        });
    });

    document.querySelectorAll('.column').forEach(column => {
        const columnId = column.id; // Ej: col-pendiente
        const cardsContainer = document.getElementById('cards-' + columnId.split('-')[1]);

        // Drag Over: Permitir soltar elementos en esta columna
        column.addEventListener('dragover', function(e) {
            e.preventDefault();
            this.classList.add('drag-over');
        });

        // Drag Leave: Remover clase de hover cuando se sale del área
        column.addEventListener('dragleave', function() {
            this.classList.remove('drag-over');
        });

        // Drop: Manejar la caída de la tarjeta en esta columna
        column.addEventListener('drop', function(e) {
            e.preventDefault();
            this.classList.remove('drag-over');

            if (draggedCard) {
                const newStatus = columnId.replace('col-', '').split('-').map(s => s.charAt(0).toUpperCase() + s.slice(1)).join(' '); // Convierte col-pendiente a Pendiente

                // 1. Actualizar el estado de la tarjeta en memoria (y potencialmente en storage)
                const cardId = parseInt(draggedCard.id.split('-')[1].replace('card-', ''));
                let cards = JSON.parse(localStorage.getItem('cards')) || [];

                const cardToUpdate = cards.find(c => c.id === cardId);
                if (cardToUpdate) {
                    cardToUpdate.status = newStatus;
                    saveCardToStorage(cardToUpdate); // Actualizar storage
                }


                // 2. Mover el elemento visualmente
                const targetContainer = document.getElementById('cards-' + columnId.split('-')[1]);
                if (targetContainer) {
                    // Limpiar y re-renderizar para asegurar que la estructura es correcta, o simplemente moverlo
                    // Para evitar problemas de DOM, lo movemos directamente:
                    targetContainer.appendChild(draggedCard);
                }

                // 3. Resetear el estado del arrastre
                draggedCard.style.opacity = '1';
            }
        });
    });
});
```

