     */
    function deleteCard(cardElement) {
        // Find the parent container (the column's list) and remove the card completely.
        const parentContainer = cardElement.parentNode;
        if (parentContainer) {
            parentContainer.removeChild(cardElement);
        } else {
             console.error("Could not find parent container for deletion.");
