        if (!targetContainer) {
            console.error(`Target container ${targetCardListId} not found.`);
            return;
        }

        // 1. Remove from current parent (optional, but good practice if we knew the source)
        const sourceParent = card.parentNode;
        if (sourceParent && sourceParent !== targetContainer) {
             sourceParent.removeChild(card);
        }

        // 2. Append to new container
        targetContainer.appendChild(card);
    }


    // --- Drag and Drop Handlers ---

    const columns = [
