            card.setAttribute('draggable', true);
            card.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', e.target.id || 'card'); // Use a generic identifier
                e.currentTarget.classList.add('dragging');
            });

            card.addEventListener('dragend', (e) => {
                e.currentTarget.classList.remove('dragging');
            });
        });


        // Drag Over Listener (on the column list container)
        if (columnElement && cardListElement) {
            cardListElement.addEventListener('dragover', (e) => {
                e.preventDefault(); // Necessary to allow dropping
                const afterElement = getDragAfterElement(cardListElement, e.clientY);

                // Visual feedback for where the card will land
                if (afterElement == null) {
                    cardListElement.appendChild(document.querySelector('.dragging'));
                } else {
                    cardListElement.insertBefore(document.querySelector('.dragging'), afterElement);
                }
            });

            // Drop Listener (on the column list container)
            cardListElement.addEventListener('drop', (e) => {
                e.preventDefault();
                const draggedCard = document.querySelector('.dragging');
                if (draggedCard) {
                    // The dragover handler already placed the card visually, 
                    // we just need to ensure it's correctly positioned and clean up classes.
                    draggedCard.classList.remove('dragging');
                }
            });
        }
    });

    /**
     * Helper function to determine where a dragged element should be inserted in the list.
     * @param {HTMLElement} container - The parent container (cardListElement).
     * @param {number} y - The vertical position of the mouse cursor.
     * @returns {HTMLElement | null} The element before which the card should be placed, or null if it should go at the end.
     */
    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.card:not(.dragging)')];

        return draggableElements.reduce((el, card) => {
            const rect = card.getBoundingClientRect();
            const center = rect.top + rect.height / 2;

            if (y < center) {
                return card; // This card is above the cursor
            } else {
                return el; // Keep tracking the potential insertion point
            }
        }, null);
    }


