     * @param {string} title - The title of the card.
     * @param {string} description - The description of the card.
     * @param {string} priority - The priority level (alta, media, baja).
     */
    function createCard(title, description, priority) {
        const cardsContainer = document.getElementById('cards-pendiente');
        if (!cardsContainer) return;

        const cardElement = document.createElement('div');
        cardElement.className = 'card card-container';
        cardElement.setAttribute('draggable', true);
