            </div>
            <div class="card-actions">
                <button class="action-btn move-to-en-curso" data-target="col-en-curso">Mover a En Curso</button>
                <button class="action-btn move-to-completa" data-target="col-completa">Mover a Completa</button>
                <button class="action-btn delete-card" data-card="${title}">Eliminar</button>
            </div>
        `;

        cardsContainer.appendChild(cardElement);
        setupCardListeners(cardElement);
