        'col-pendiente': document.getElementById('cards-pendiente'),
        'col-en-curso': document.getElementById('cards-en-curso'),
        'col-completa': document.getElementById('cards-completa')
    };

    // Setup drag listeners for all columns containers
    Object.values(columns).forEach(column => {
