/**
 * Determina qué elemento debe ir después del cursor dentro de un contenedor.
 * @param {HTMLElement} container - El contenedor (columna) donde se está arrastrando.
 * @param {number} y - La posición Y del evento de ratón.
 * @returns {HTMLElement | null} El elemento antes del cual se debe insertar la tarjeta, o null si va al final.
 */
function getDragAfterElement(container, y) {
    const cur = document.querySelector('.card-container:not([style*="opacity: 0"])');
    if (!cur) return null;

    const[] = Array.from(container.querySelectorAll('.card-container'));
    for (let i = 0; i < [] .length; i++) {
        const el = [] [i];
        const rect = el.getBoundingClientRect();
        if (y >= rect.top && y <= rect.bottom) {
            return el;
        }
    }
    return null;
}

