        document.getElementById('cardId').value = ''; // Limpiar ID si existe
    }

    function closeModal() {
        modal.style.display = 'none';
        document.body.classList.remove('modal-open');
    }

    // Event listener para cerrar el modal al hacer clic fuera
    window.addEventListener('click', (e) => {
        if (e.target === modal) {
            closeModal();
        }
    });

    saveCardBtn.addEventListener('click', saveCard);

    function saveCard() {
        const title = document.getElementById('title').value.trim();
        const description = document.getElementById('description').value.trim();
        const priority = document.getElementById('priority').value;
        const cardId = document.getElementById('cardId').value;

        if (!title || !description) {
            alert('Por favor, complete todos los campos.');
            return;
        }

        let cardElement;

        if (cardId) {
            // Editar tarjeta existente
            cardElement = document.querySelector(`.card[data-id="${cardId}"]`);
            if (!cardElement) return; // No encontrar la tarjeta a editar

            // Actualizar contenido de la tarjeta
            cardElement.querySelector('.card-title').textContent = title;
            cardElement.querySelector('.card-description').textContent = description;
            const priorityTag = cardElement.querySelector('.priority-tag');
            if (priorityTag) {
                priorityTag.className = `priority-tag ${getPriorityClass(priority)}`;
                priorityTag.textContent = priority.toUpperCase();
            }

        } else {
            // Crear tarjeta nueva
            cardElement = createCardElement(title, description, priority);
            const cardContainerId = 'cards-' + document.getElementById('col-pendiente').getAttribute('data-column').split('-')[1];
            document.getElementById(cardContainerId).appendChild(cardElement);
        }

        // Cerrar modal y limpiar
        closeModal();
    }

    function createCardElement(title, description, priority) {
        const card = document.createElement('div');
        card.className = 'card';
        card.setAttribute('draggable', true);
        card.setAttribute('data-column', 'Pendiente'); // Inicialmente en Pendiente
        card.setAttribute('data-id', Date.now().toString());

        const priorityClass = getPriorityClass(priority);

        card.innerHTML = `
            <div class="card-body">
                <h3 class="card-title">${title}</h3>
                <p class="card-description">${description}</p>
                <span class="priority-tag ${priorityClass}">${priority.toUpperCase()}</span>
            </div>
            <div class="card-actions">
                <button class="action-btn edit-btn" data-id="${card.getAttribute('data-id')}">Editar</button>
                <button class="action-btn delete-btn" data-id="${card.getAttribute('data-id')}">Eliminar</button>
            </div>
        `;

        // Añadir listeners a los botones de la tarjeta recién creada
        card.querySelector('.edit-btn').addEventListener('click', (e) => {
            const id = e.target.dataset.id;
            loadCardForEdit(id);
        });
        card.querySelector('.delete-btn').addEventListener('click', (e) => {
            if (confirm('¿Está seguro de que desea eliminar esta tarjeta?')) {
                e.target.closest('.card').remove();
            }
        });

        return card;
    }

    function getPriorityClass(priority) {
        switch (priority.toLowerCase()) {
            case 'alta': return 'priority-alta';
            case 'media': return 'priority-media';
            case 'baja': return 'priority-baja';
            default: return '';
        }
    }

    function loadCardForEdit(id) {
        const cardElement = document.querySelector(`.card[data-id="${id}"]`);
        if (!cardElement) return;

        // Llenar el modal con los datos de la tarjeta
        document.getElementById('title').value = cardElement.querySelector('.card-title').textContent;
        document.getElementById('description').value = cardElement.querySelector('.card-description').textContent;
        const priorityTag = cardElement.querySelector('.priority-tag');
        if (priorityTag) {
            document.getElementById('priority').value = priorityTag.textContent.toLowerCase();
        }

        // Configurar el ID para saber que estamos editando
        document.getElementById('cardId').value = id;

        openModal();
    }


