```javascript
// Variables globales para manejar el estado de la aplicación
let cards = [];
const columns = {
    'pendiente': { title: 'Pendiente', count: 0, elementId: 'col-pendiente' },
    'en_curso': { title: 'En Curso', count: 0, elementId: 'col-en-curso' },
    'completa': { title: 'Completa', count: 0, elementId: 'col-completa' }
};

// Elementos del DOM
const board = document.querySelector('.board');
const cardModal = document.getElementById('cardModal');
const modalTitle = document.getElementById('modalTitle');
const cardForm = document.getElementById('cardForm');
const saveCardBtn = document.getElementById('saveCardBtn');

// --- Inicialización y Renderizado del Tablero ---

/**
 * Inicializa la estructura de las columnas en el tablero.
 */
function initializeBoard() {
    board.innerHTML = ''; // Limpiar contenido previo
    Object.keys(columns).forEach(key => {
        const colData = columns[key];
        let columnElement = document.getElementById(colData.elementId);

        if (!columnElement) {
            // Crear la estructura de la columna si no existe
            columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.id = colData.elementId;
            columnElement.setAttribute('data-status', key);

            // Estructura: Header (Título + Contador) -> Cards Container -> Add Card Button (solo en Pendiente)
            columnElement.innerHTML = `
                <div class="column-header">
                    <h2>${colData.title}</h2>
                    <span class="card-counter" id="${key}-count">0</span>
                </div>
                <div class="cards-container" id="cards-${key}"></div>
            `;
            board.appendChild(columnElement);
        } else {
            // Si ya existe, solo aseguramos que los elementos internos estén correctos (aunque en este caso se reconstruye todo)
            // Para mantener la compatibilidad con el estado inicial, simplemente lo dejamos como está si es necesario, pero para una limpieza total, re-renderizamos.
        }

        // Añadir botón "Agregar tarjeta" solo a 'Pendiente'
        if (key === 'pendiente') {
            let addCardBtn = document.getElementById('addCardBtnBottom');
            if (!addCardBtn) {
                addCardBtn = document.createElement('button');
                addCardBtn.id = 'addCardBtnBottom';
                addCardBtn.className = 'btn-primary';
                addCardBtn.textContent = 'Agregar tarjeta';
                addCardBtn.addEventListener('click', () => openModal(key));
                columnElement.appendChild(addCardBtn);
            }
        } else {
             // Asegurarse de que no haya botón en otras columnas
             const existingButton = document.getElementById('addCardBtnBottom');
             if (existingButton && !['pendiente'].includes(Object.keys(columns).find(k => columns[k].elementId === columnElement.id))) {
                 columnElement.removeChild(existingButton);
             }
        }
    });

    // Inicializar el estado de las tarjetas y los contadores
    renderCards();
}


/**
 * Abre el modal para crear una nueva tarjeta, pre-seleccionando la columna actual.
 * @param {string} status - El estado (pendiente, en_curso, completa) donde se creará la tarjeta.
 */
function openModal(status) {
    // Lógica de apertura del modal y configuración del formulario
    modalTitle.textContent = `Crear nueva tarjeta en ${columns[status].title}`;
    cardForm.reset();
    document.getElementById('currentColumn').value = status; // Establecer la columna actual
    cardModal.style.display = 'block';
}

/**
 * Cierra el modal de creación de tarjetas.
 */
function closeModal() {
    cardModal.style.display = 'none';
}


// --- Lógica de Tarjetas y Contadores ---

/**
 * Renderiza todas las tarjetas en sus respectivas columnas y actualiza los contadores.
 */
function renderCards() {
    // Limpiar contenedores antes de renderizar
    Object.keys(columns).forEach(key => {
        document.getElementById(`cards-${key}`).innerHTML = '';
    });

    let cardCounts = {};
    Object.keys(columns).forEach(key => {
        cardCounts[key] = 0;
    });

    // Renderizar cada tarjeta
    cards.forEach(card => {
        const containerId = `cards-${card.status}`;
        const container = document.getElementById(containerId);
        if (container) {
            const cardElement = createCardElement(card);
            container.appendChild(cardElement);
            cardCounts[card.status]++;
        }
    });

    // Actualizar contadores de columna
    Object.keys(columns).forEach(key => {
        const countSpan = document.getElementById(`${key}-count`);
        if (countSpan) {
            countSpan.textContent = cardCounts[key];
        }
    });
}

/**
 * Crea el elemento HTML para una tarjeta individual.
 * @param {object} card - Objeto de la tarjeta.
 * @returns {HTMLElement} El elemento div de la tarjeta.
 */
function createCardElement(card) {
    const cardDiv = document.createElement('div');
    cardDiv.className = 'card';
    cardDiv.setAttribute('draggable', true);
    cardDiv.dataset.id = card.id;

    // Contenido de la tarjeta
    cardDiv.innerHTML = `
        <div class="drag-handle"></div>
        <div class="card-body">
            <h4 class="card-title">${card.title}</h4>
            <p class="card-description">${card.description}</p>
            <span class="priority-tag priority-${card.priority}">Prioridad: ${card.priority.toUpperCase()}</span>
        </div>
        <div class="card-actions">
            <button class="action-btn" data-action="view">Ver</button>
            <button class="action-btn" data-action="edit">Editar</button>
        </div>
    `;

    // Añadir listeners de arrastrar y soltar (Drag and Drop)
    cardDiv.addEventListener('dragstart', handleDragStart);
    cardDiv.addEventListener('dragend', handleDragEnd);

    return cardDiv;
}


// --- Manejo de Eventos Globales ---

/**
 * Maneja el inicio del arrastre de una tarjeta.
 * @param {Event} e - El evento dragstart.
 */
function handleDragStart(e) {
    const cardId = e.target.dataset.id;
    e.dataTransfer.setData('text/plain', cardId);
    e.dataTransfer.effectAllowed = 'move';

    // Añadir clase de arrastre visualmente
    setTimeout(() => {
        e.target.classList.add('dragging');
    }, 0);
}

/**
 * Maneja el final del arrastre de una tarjeta.
 * @param {Event} e - El evento dragend.
 */
function handleDragEnd(e) {
    // Remover clase de arrastre visualmente
    e.target.classList.remove('dragging');
}


/**
 * Configura los listeners para las zonas de drop (columnas).
 */
function setupDropZones() {
    const columnsContainers = document.querySelectorAll('.cards-container');

    columnsContainers.forEach(container => {
        // Dragover: Previene el comportamiento por defecto y permite soltar
        container.addEventListener('dragover', (e) => {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move'; // Indica que se puede mover
        });

        // Drop: Maneja la lógica de movimiento al soltar
        container.addEventListener('drop', handleDrop);
    });
}

/**
 * Maneja el evento de soltado de una tarjeta en una columna.
 * @param {Event} e - El evento drop.
 */
function handleDrop(e) {
    e.preventDefault();
    const cardId = e.dataTransfer.getData('text/plain');
    const targetContainer = e.currentTarget;
    const newStatus = targetContainer.id.replace('cards-', '');

    if (cardId && newStatus) {
        moveCard(cardId, newStatus);
    }
}

/**
 * Mueve una tarjeta de un estado a otro y actualiza el estado global.
 * @param {string} cardId - ID de la tarjeta a mover.
 * @param {string} newStatus - Nuevo estado (pendiente, en_curso, completa).
 */
function moveCard(cardId, newStatus) {
    const cardIndex = cards.findIndex(c => c.id === cardId);
    if (cardIndex !== -1 && cards[cardIndex].status !== newStatus) {
        // Actualizar el estado de la tarjeta en el array global
        cards[cardIndex].status = newStatus;

        // Re-renderizar todo para actualizar posiciones y contadores
        renderCards();
    }
}


/**
 * Maneja el envío del formulario de creación/edición de tarjetas.
 * @param {Event} e - El evento submit.
 */
function handleFormSubmit(e) {
    e.preventDefault();

    const title = document.getElementById('title').value.trim();
    const description = document.getElementById('description').value.trim();
    const priority = document.getElementById('priority').value;
    const status = document.getElementById('currentColumn').value; // Columna de destino

    if (!title || !description) {
        alert('Por favor, complete todos los campos.');
        return;
    }

    // Si es una edición (se podría añadir lógica para saber si se edita o crea)
    const cardId = document.getElementById('cardId').value;

    if (cardId) {
        // Edición de tarjeta existente
        const cardIndex = cards.findIndex(c => c.id === cardId);
        if (cardIndex !== -1) {
            cards[cardIndex] = { id: cardId, title, description, priority, status };
        }
    } else {
        // Creación de tarjeta nueva
        const newCard = {
            id: Date.now().toString(), // ID único simple
            title: title,
            description: description,
            priority: priority,
            status: status
        };
        cards.push(newCard);
    }

    // Limpiar y actualizar la vista
    closeModal();
    renderCards();
}


// --- Inicialización de Event Listeners al cargar el DOM ---
document.addEventListener('DOMContentLoaded', () => {
    initializeBoard(); // 1. Configura la estructura del tablero (incluyendo botones)
    setupDropZones();  // 2. Asigna listeners de arrastrar y soltar

    // Listeners para el Modal
    saveCardBtn.addEventListener('click', handleFormSubmit);
    document.getElementById('cardModal').addEventListener('click', (e) => {
        if (e.target === cardModal) {
            closeModal();
        }
    });
});

