document.addEventListener('DOMContentLoaded', () => {
    const board = document.querySelector('.board');
    if (!board) return;

    // --- DOM Elements ---
    const colPendiente = document.getElementById('col-pendiente');
    const colEnCurso = document.getElementById('col-en-curso');
