    const cardsPendienteContainer = document.getElementById('cards-pendiente');
    const cardsEnCursoContainer = document.getElementById('cards-en-curso');
    const cardsCompletaContainer = document.getElementById('cards-completa');

    // Buttons for adding cards (assuming these are the elements that need control)
