    const saveCardBtn = document.getElementById('saveCardBtn');
    const cardIdInput = document.getElementById('cardId');
    const currentColumnSelect = document.getElementById('currentColumn');

    // --- State Management ---
    let cards = JSON.parse(localStorage.getItem('cards')) || [];
    let nextCardId = cards.length > 0 ? Math.max(...cards.map(c => c.id)) + 1 : 1;

    // --- Utility Functions ---

    /**
     * Saves the current state of cards to local storage.
     */
    const saveCards = () => {
        localStorage.setItem('cards', JSON.stringify(cards));
    };

    /**
     * Generates HTML for a single card element.
     * @param {Object} card - The card object.
     * @returns {string} HTML string of the card.
     */
    const createCardElement = (card) => {
        return `
            <div class="card" draggable="true" data-id="${card.id}" data-priority="${card.priority}">
                <div class="drag-handle"></div>
                <div class="card-body">
                    <h4 class="card-title">${card.title}</h4>
                    <p class="card-description">${card.description}</p>
                    <div class="priority-tag ${card.priority}-tag">${card.priority}</div>
                </div>
                <div class="card-actions">
                    <button class="action-btn view-details" data-id="${card.id}">Ver</button>
                </div>
            </div>
        `;
    };

    /**
     * Renders all cards into their respective column containers.
     */
    const renderBoard = () => {
        // Clear existing cards
        cardsPendienteContainer.innerHTML = '';
        cardsEnCursoContainer.innerHTML = '';
        cardsCompletaContainer.innerHTML = '';

        // Group and render
        const columnsMap = {
            'Pendiente': [ ...cards.filter(c => c.status === 'Pendiente') ],
            'En Curso': [ ...cards.filter(c => c.status === 'En Curso') ],
            'Completa': [ ...cards.filter(c => c.status === 'Completa') ]
        };

        // Render cards in order
        columnsMap['Pendiente'].forEach(card => {
            cardsPendienteContainer.innerHTML += createCardElement(card);
        });
        columnsMap['En Curso'].forEach(card => {
            cardsEnCursoContainer.innerHTML += createCardElement(card);
        });
        columnsMap['Completa'].forEach(card => {
            cardsCompletaContainer.innerHTML += createCardElement(card);
        });

        // Re-attach event listeners after rendering
        setupDragAndDrop();
        setupEventListeners();
    };

    /**
     * Updates the counter displayed in each column header.
     */
    const updateCounters = () => {
        const countPendiente = cards.filter(c => c.status === 'Pendiente').length;
        const countEnCurso = cards.filter(c => c.status === 'En Curso').length;
        const countCompleta = cards.filter(c => c.status === 'Completa').length;

        document.getElementById('counter-pendiente').textContent = countPendiente;
        document.getElementById('counter-en-curso').textContent = countEnCurso;
        document.getElementById('counter-completa').textContent = countCompleta;
    };

    /**
     * Handles the addition of a new card to the board.
     */
    const addCard = (title, description, priority) => {
        const newCard = {
            id: nextCardId++,
            title: title,
            description: description,
            priority: priority,
            status: 'Pendiente' // New cards always start in Pendiente
        };
        cards.push(newCard);
        saveCards();
        renderBoard();
        updateCounters();
    };

    /**
     * Updates the card status when dragged to a new column.
     * @param {number} cardId - ID of the card being moved.
     * @param {string} newStatus - The target status ('Pendiente', 'En Curso', 'Completa').
     */
    const updateCardStatus = (cardId, newStatus) => {
        const cardIndex = cards.findIndex(c => c.id == cardId);
        if (cardIndex !== -1 && cards[cardIndex].status !== newStatus) {
            cards[cardIndex].status = newStatus;
            saveCards();
            renderBoard(); // Re-render to reflect status change and update counters
        }
    };

    // --- Event Handlers ---

    /**
     * Handles the drag start event for cards.
     */
    const handleDragStart = (e) => {
        const cardElement = e.target.closest('.card');
        if (!cardElement) return;
        e.dataTransfer.setData('text/plain', cardElement.dataset.id);
        e.dataTransfer.effectAllowed = 'move';
    };

    /**
     * Handles the drag over event for columns (drop zones).
     */
    const handleDragOver = (e) => {
        e.preventDefault(); // Necessary to allow dropping
        const targetColumn = e.currentTarget;
        if (targetColumn && !targetColumn.classList.contains('hidden')) {
            e.dataTransfer.dropEffect = 'move';
        }
    };

    /**
     * Handles the drag leave event for columns.
     */
    const handleDragLeave = (e) => {
        // Optional: Remove visual feedback when leaving a column
    };

    /**
     * Handles the drop event on a column.
     */
    const handleDrop = (e) => {
        e.preventDefault();
        const cardId = e.dataTransfer.getData('text/plain');
        const targetColumnElement = e.currentTarget;
        let newStatus = '';

        if (targetColumnElement.id === 'col-pendiente') {
            newStatus = 'Pendiente';
        } else if (targetColumnElement.id === 'col-en-curso') {
            newStatus = 'En Curso';
        } else if (targetColumnElement.id === 'col-completa') {
            newStatus = 'Completa';
        }

        if (newStatus) {
            updateCardStatus(cardId, newStatus);
        }
    };

    /**
     * Sets up drag and drop listeners on the board columns.
     */
    const setupDragAndDrop = () => {
        // Remove previous listeners to prevent duplication
        [colPendiente, colEnCurso, colCompleta].forEach(col => {
            if (col) {
                col.removeEventListener('dragover', handleDragOver);
                col.removeEventListener('dragleave', handleDragLeave);
                col.removeEventListener('drop', handleDrop);
            }
        });

        // Add listeners to columns
        [colPendiente, colEnCurso, colCompleta].forEach(col => {
            if (col) {
                col.addEventListener('dragover', handleDragOver);
                col.addEventListener('dragleave', handleDragLeave);
                col.addEventListener('drop', handleDrop);
            }
        });

        // Add listeners to cards for drag start
        document.querySelectorAll('.card').forEach(card => {
            card.removeEventListener('dragstart', handleDragStart); // Clean up old listeners
            card.addEventListener('dragstart', handleDragStart);
        });
    };


    /**
     * Sets up all remaining event listeners (buttons, modals, etc.).
     */
    const setupEventListeners = () => {
        // 1. Card Actions (View Details)
        document.querySelectorAll('.view-details').forEach(button => {
            button.onclick = (e) => {
                const cardId = e.target.dataset.id;
                const card = cards.find(c => c.id == cardId);
                if (card) {
                    displayCardDetails(card);
                }
            };
        });

        // 2. Modal Close/Cancel
        document.querySelector('.modal-close').onclick = () => {
            cardModal.classList.add('hidden');
        };
        window.onclick = (event) => {
            if (event.target === cardModal) {
                cardModal.classList.add('hidden');
            }
        };

        // 3. Form Submission (Save Card)
        saveCardBtn.onclick = () => {
            const title = document.getElementById('title').value.trim();
            const description = document.getElementById('description').value.trim();
            const priority = document.getElementById('priority').value;

            if (!title || !description || !priority) {
                alert('Por favor, complete todos los campos.');
                return;
            }

            // If editing an existing card (using the modal flow for simplicity in this fix context)
            const cardId = document.getElementById('cardId').value;
            if (cardId && !isNaN(parseInt(cardId))) {
                const index = cards.findIndex(c => c.id == cardId);
                if (index !== -1) {
                    cards[index].title = title;
                    cards[index].description = description;
                    cards[index].priority = priority;
                    saveCards();
                    renderBoard();
                    updateCounters();
                    alert('Tarjeta actualizada con éxito.');
                }
            } else {
                // Adding a new card (always starts in Pendiente)
                addCard(title, description, priority);
            }

            cardModal.classList.add('hidden');
        };


        // 4. Add Card Button Listener (The critical fix area)
        if (addCardBtnBottomPendiente) {
            addCardBtnBottomPendiente.onclick = () => {
                // Open modal for adding a new card
                modalTitle.textContent = 'Agregar Nueva Tarjeta';
                document.getElementById('title').value = '';
                document.getElementById('description').value = '';
                document.getElementById('priority').value = 'media';
                document.getElementById('cardId').value = ''; // Clear ID for new card
                cardModal.classList.remove('hidden');
            };
        }

        // 5. Initial Setup Call
        renderBoard();
        updateCounters();
    };


    /**
     * Displays the details of a specific card in the modal (for viewing/editing).
     * @param {Object} card - The card object to display.
     */
    const displayCardDetails = (card) => {
        modalTitle.textContent = `Detalles de la Tarjeta: ${card.title}`;
        document.getElementById('cardId').value = card.id;
        document.getElementById('title').value = card.title;
